/**
 * Analiza /analizy/lekarze-radni/: oczyszczony zbiór oświadczeń majątkowych radnych, którzy są lekarzami.
 * Tekst i przypisy są w content/articles/lekarze-radni.mdx — tu wiersze zbioru, statystyki liczone
 * z tych wierszy i gotowe tabele dla bloków w artykule (Comparison, BarChart, radni/RadniTable).
 *
 * Skąd dane: zbiór zebrał społecznie jeden z czytelników (stan 14.08.2026; w research.db tabela
 * `radni_lekarze`, 184 wiersze, z czego 1 to małżonka radnego, a nie radna). Redakcja otworzyła
 * każde dostępne oświadczenie i porównała je ze zbiorem (15.10.2026; raporty weryfikacji
 * poza repozytorium). `nr` = pozycja w tamtych raportach
 * (zbiór posortowany malejąco po dochodzie, bez małżonki).
 *
 * Wyłączone: 1 wiersz osoby, wobec której toczy się postępowanie karne (zasada serwisu: wiersze
 * osób z postępowaniami w toku wyłączamy). Nie opisujemy go tu, żeby nie dało się go rozpoznać.
 * Bez nazwisk — kolumna `nazwisko` z bazy nie trafia do serwisu.
 *
 * Definicje:
 * - `dzialalnosc` — dochód z własnej praktyki lub działalności leczniczej (JDG, gabinet, spółka
 *   cywilna, jawna, partnerska), jak podaje oświadczenie. null, gdy oświadczenie podaje tylko przychód,
 *   gdy radny nie prowadzi praktyki albo gdy kwoty nie da się ustalić (`rodzaj` mówi, który to przypadek).
 * - `laczny` — dochód z pracy ze wszystkich odnotowanych tytułów: praktyka, etat, umowy, zarząd
 *   i dywidenda ze spółki. Bez diety radnego, emerytury, najmu, kapitału i dochodów małżonka.
 *   To dolna granica — drobne tytuły mogły nie zostać odnotowane.
 * - `przychod` — przychód z praktyki (przed kosztami), gdy oświadczenie go podaje.
 * - `rok` — rok, za który jest dochód (data złożenia minus 1), po poprawce; `zbior.rok` — rok w zbiorze.
 * - `status`: zgodne = kwota i rok zbioru są w oświadczeniu (także gdy kwota była sumą tytułów —
 *   wtedy `bledy` ma 'suma', a my rozdzielamy praktykę i dochód łączny); poprawione = zbiór miał inną
 *   kwotę, rok albo przychód zamiast dochodu; niepewne = oświadczenie nie rozstrzyga; niedostepne =
 *   brak oświadczenia pod linkiem.
 * Kwoty w pełnych złotych (grosze obcięte, jak w zbiorze).
 */
import { formatPL } from '@/lib/format';
import type { BarRow, CompareTable } from '@/types';

export const LINKS = {
  /** ustawa o samorządzie gminnym, t.j. Dz.U. 2026 poz. 662 — art. 24h i 24i */
  usg: 'https://api.sejm.gov.pl/eli/acts/DU/2026/662/text.pdf',
  /** ustawa o samorządzie powiatowym, t.j. Dz.U. 2025 poz. 1684 — art. 25c i 25d */
  usp: 'https://api.sejm.gov.pl/eli/acts/DU/2025/1684/text.pdf',
  /** ustawa o samorządzie województwa, t.j. Dz.U. 2026 poz. 720 — art. 27c i 27d */
  usw: 'https://api.sejm.gov.pl/eli/acts/DU/2026/720/text.pdf',
  /** Rzeczpospolita: własna analiza oświadczeń radnych-lekarzy, najwyższy dochód 2,15 mln zł za 2025 r. */
  rp: 'https://www.rp.pl/polityka/art44928601-ponad-milion-zlotych-za-rok-pracy-dla-lekarza-radnego-w-polsce-wyniki-analizy',
  /** Co w Zdrowiu: inny zbiór — 160 oświadczeń, mediana ok. 285 tys. zł, maksimum 4,9 mln zł */
  cowzdrowiu: 'https://cowzdrowiu.pl/aktualnosci/post/ile-zarabiaja-lekarze-radni-rekord-to-49-mln-zl',
};

export type Typ = 'gmina' | 'powiat' | 'województwo';
/** czym jest kwota praktyki w oświadczeniu */
export type Rodzaj = 'dochod' | 'jednaKwota' | 'tylkoPrzychod' | 'brakPraktyki' | 'nieustalony';
export type Status = 'zgodne' | 'poprawione' | 'niepewne' | 'niedostepne';
/** co było nie tak w zbiorze */
export type Blad = 'kwota' | 'rok' | 'brakRoku' | 'przychod' | 'suma' | 'strata' | 'zaokraglenie';

export interface Radny {
  nr: number;
  rada: string;
  typ: Typ;
  /** rok, za który jest dochód; null = nieznany */
  rok: number | null;
  /** tytuły, z których pochodzi dochód, według oświadczenia */
  forma: string;
  /** specjalność według autora zbioru (oświadczenia jej nie podają), bez wpisów, które nie są specjalnością */
  spec?: string;
  dzialalnosc: number | null;
  rodzaj: Rodzaj;
  laczny: number | null;
  przychod: number | null;
  status: Status;
  bledy: Blad[];
  uwaga?: string;
  /** oświadczenie w BIP (plik albo strona z listą oświadczeń); null = brak działającego linku */
  link: string | null;
  /** wartości z pierwotnego zbioru — do porównania */
  zbior: { rok: number | null; dochod: number; przychod: number | null };
}

/** Pierwotny zbiór i to, co z niego wyłączyliśmy. */
