// ————————————————— statystyki —————————————————

/** Do statystyk wchodzą tylko wiersze, których kwotę potwierdza oświadczenie. */
const W_STATYSTYKACH: Status[] = ['zgodne', 'poprawione'];
export const LATA = [2025, 2024] as const;
export type Rok = (typeof LATA)[number];
export type Miara = 'dzialalnosc' | 'laczny';

const mediana = (xs: number[]) => {
  const s = [...xs].sort((a, b) => a - b);
  const m = s.length >> 1;
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};

export interface Statystyka {
  rok: Rok;
  /** wszystkie opublikowane wiersze za ten rok */
  wierszy: number;
  /** wiersze w statystyce (status zgodne/poprawione i znana kwota) */
  n: number;
  /** w tym wiersze, w których praktyka to jedna kwota „przychód i dochód” */
  jednaKwota: number;
  mediana: number;
  od500: number;
  od1mln: number;
  max: number;
}

const policz = (miara: Miara, rok: Rok): Statystyka => {
  const wRoku = RADNI.filter((r) => r.rok === rok);
  const wiersze = wRoku.filter((r) => W_STATYSTYKACH.includes(r.status) && r[miara] != null);
  const xs = wiersze.map((r) => r[miara] as number);
  return {
    rok,
    wierszy: wRoku.length,
    n: xs.length,
    jednaKwota: wiersze.filter((r) => r.rodzaj === 'jednaKwota').length,
    mediana: Math.round(mediana(xs)),
    od500: xs.filter((x) => x >= 500_000).length,
    od1mln: xs.filter((x) => x >= 1_000_000).length,
    max: Math.max(...xs),
  };
};

export const STATS: Record<Miara, Record<Rok, Statystyka>> = {
  dzialalnosc: { 2025: policz('dzialalnosc', 2025), 2024: policz('dzialalnosc', 2024) },
  laczny: { 2025: policz('laczny', 2025), 2024: policz('laczny', 2024) },
};

const zlicz = <K extends string>(klucze: K[]) => Object.fromEntries(klucze.map((k) => [k, 0])) as Record<K, number>;

export const STATUS: Record<Status, number> = zlicz<Status>(['zgodne', 'poprawione', 'niepewne', 'niedostepne']);
export const RODZAJ: Record<Rodzaj, number> = zlicz<Rodzaj>(['dochod', 'jednaKwota', 'tylkoPrzychod', 'brakPraktyki', 'nieustalony']);
export const BLEDY: Record<Blad, number> = zlicz<Blad>(['kwota', 'rok', 'brakRoku', 'przychod', 'suma', 'strata', 'zaokraglenie']);
for (const r of RADNI) {
  STATUS[r.status]++;
  RODZAJ[r.rodzaj]++;
  for (const b of r.bledy) BLEDY[b]++;
}

/** opublikowane wiersze (bez małżonki i bez wiersza z postępowaniem w toku) */
export const WIERSZY = RADNI.length;
/** wiersze z jakimkolwiek błędem poza samym nazwaniem sumy tytułów „dochodem” */
export const Z_BLEDEM = RADNI.filter((r) => r.bledy.some((b) => b !== 'suma')).length;
/** wiersze bez roku 2024 ani 2025 (rok nieznany albo inny) */
export const POZA_LATAMI = RADNI.filter((r) => r.rok !== 2024 && r.rok !== 2025).length;

/** Praktyka a etat: w ilu wierszach z obiema kwotami praktyka to mniej niż połowa dochodu z pracy. */
const zObiema = RADNI.filter((r) => W_STATYSTYKACH.includes(r.status) && r.dzialalnosc != null && r.laczny != null);
export const PRAKTYKA = {
  zObiema: zObiema.length,
  ponizejPolowy: zObiema.filter((r) => (r.dzialalnosc as number) < 0.5 * (r.laczny as number)).length,
  /** dochód z pracy bez praktyki (etat, umowy, dywidenda) */
  bezPraktyki: RADNI.filter((r) => W_STATYSTYKACH.includes(r.status) && r.rodzaj === 'brakPraktyki').length,
};

/** Wiersz z najwyższym przychodem z praktyki (spośród potwierdzonych) — przykład, że przychód to nie dochód. */
export const MAX_PRZYCHOD = RADNI.filter((r) => W_STATYSTYKACH.includes(r.status) && r.przychod != null && r.dzialalnosc != null).reduce((a, b) =>
  (b.przychod as number) > (a.przychod as number) ? b : a,
);

/** Liczby ze starej wersji strony (stan 14.08.2026) — tylko do porównania w sekcji o metodzie. */
export const STARE = { wierszy: 183, mediana: 632_598, od500: 117, od1mln: 30, max: 2_149_835 } as const;

// ————————————————— gotowe tabele i wykresy dla artykułu —————————————————

const zl = (n: number) => `${formatPL(n)} zł`;
const tys = (n: number) => `${formatPL(n / 1000, 1)} tys. zł`;

/** Statystyki jednej miary za oba lata, z liczbą wierszy w każdej. */
export const statsTable = (miara: Miara): CompareTable => {
  const s = LATA.map((rok) => STATS[miara][rok]);
  return {
    columns: ['', ...LATA.map((rok) => `Za ${rok} r.`)],
    rows: [
      { cells: ['Wierszy w statystyce', ...s.map((x) => `${x.n} z ${x.wierszy} (w tym ${x.jednaKwota} z jedną kwotą „przychód i dochód”)`)] },
      { cells: ['Mediana', ...s.map((x) => tys(x.mediana))], marked: true },
      { cells: ['500 tys. zł i więcej', ...s.map((x) => `${x.od500} z ${x.n}`)] },
      { cells: ['1 mln zł i więcej', ...s.map((x) => `${x.od1mln} z ${x.n}`)] },
      { cells: ['Najwyższy', ...s.map((x) => zl(x.max))] },
    ],
  };
};

const PRZEDZIALY = [
  { label: 'poniżej 250 tys. zł', od: 0, do: 250_000 },
  { label: '250–500 tys. zł', od: 250_000, do: 500_000 },
  { label: '500–750 tys. zł', od: 500_000, do: 750_000 },
  { label: '750 tys. – 1 mln zł', od: 750_000, do: 1_000_000 },
  { label: '1–1,5 mln zł', od: 1_000_000, do: 1_500_000 },
  { label: '1,5 mln zł i więcej', od: 1_500_000, do: Infinity },
];

/** Rozkład dochodu z pracy łącznie za jeden rok (tylko wiersze w statystyce). */
export const rozklad = (rok: Rok): BarRow[] => {
  const xs = RADNI.filter((r) => r.rok === rok && W_STATYSTYKACH.includes(r.status) && r.laczny != null).map((r) => r.laczny as number);
  return PRZEDZIALY.map((p) => {
    const n = xs.filter((x) => x >= p.od && x < p.do).length;
    return { label: p.label, value: n, display: String(n), highlight: p.od >= 1_000_000 };
  });
};

